def page_map
    @page_map ||= JSON.parse(self.page_map_json) rescue {}
  end

  def page_map=(map)
    @page_map = map
    self.page_map_json = map.to_json
  end

  # Returns the text of the page, or nil if the page is not found.
  def text
    return nil unless self.text_json
    JSON.parse(self.text_json).values.join("\n")
  end

  # Sets the text of the page from a string.
  def text=(text_string)
    self.text_json = { '0' => text_string }.to_json
  end

  # Returns the text of the page, broken down by text block.
  def text_blocks
    @text_blocks ||= JSON.parse(self.text_json) rescue {}
  end

  # Returns the text of the page, broken down by text block.
  def text_blocks=(blocks)
    @text_blocks = blocks
    self.text_json = blocks.to_json
  end

