  # create a new question, at POST /questions
  def create
    if current_user == nil
      redirect_to new_user_session_path( return_to: request.path )
      flash[:notice] = "Your question is important and we want to hear from you! Please log in or sign up to post a question"
    else
      @question = Node.new(question_params)
      @question.uid = current_user.uid
      @question.type = 'note'
      @question.status = 1 # Published
      if @question.save
        flash[:notice] = "Your question has been posted."
        redirect_to question_path(@question)
      else
        render :new
      end
    end
  end

